import type { Metadata } from "next";
import { brand } from "@/data/site";

// Generated by src/app/opengraph-image.tsx; referenced explicitly so every page carries it.
export const ogImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${brand.name} — Herbal Hair Oil in Pakistan`,
};

type PageMeta = {
  title: string;
  description: string;
  path: string;
  ogTitle?: string;
  ogDescription?: string;
  ogType?: "website" | "article" | "product";
  publishedTime?: string;
};

export function pageMetadata({
  title,
  description,
  path,
  ogTitle = title,
  ogDescription = description,
  ogType = "website",
  publishedTime,
}: PageMeta): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    // A page's openGraph replaces the layout's, so shared fields are set here.
    openGraph: {
      siteName: brand.name,
      locale: "en_PK",
      title: ogTitle,
      description: ogDescription,
      url: path,
      images: [ogImage],
      // Next's OpenGraph types have no "product"; it is emitted via `other` below.
      ...(ogType === "product" ? {} : { type: ogType }),
      ...(publishedTime && { publishedTime }),
    },
    twitter: {
      card: "summary_large_image",
      title: ogTitle,
      description: ogDescription,
      images: [ogImage.url],
    },
    ...(ogType === "product" && { other: { "og:type": "product" } }),
  };
}
